        LOG("buy", name, "paid", M.fmt(math.max(0, m0 - M.money())), "cash", M.fmt(M.money()))
        S.spent += math.max(0, m0 - M.money())
        F.heldPaid = { [M.held()] = math.max(0, m0 - M.money()) > 0 and (m0 - M.money()) or nil }
        local inf = M.info(name)
        if inf then
            S.rar[inf.rarity] = (S.rar[inf.rarity] or 0) + 1
            if not S.best or (inf.income or 0) > (S.best.income or 0) then S.best = inf end
            if M.rank(inf.rarity) >= 5 then notify(inf.rarity .. ": " .. tostring(inf.displayName or name)) end
        end
