end
function F.openCrate()
    local c = F.crate
    if not (c and on("f_crates")) or M.held() then return false end
    local price = tonumber(c.price) or 0
    local limit = math.min(M.money() * (tonumber(val("f_crateMax", 25)) or 25) / 100, M.money() - F.keep())
    F.crate = nil
    if price > limit then M.call("CrateAction", "discard") return false end
    local r = M.call("CrateAction", "open")
    if type(r) == "table" and r.ok then S.crates += 1 LOG("crate", c.name, r.prize) return true end
    LOG("crate fail", c.name, type(r) == "table" and tostring(r.reason) or "nil")
    return false
end
F.heldPaid = {}
function F.upgradeHeld(h)
    local name = F.roll()
    if not name or not M.held() then return false end
    local inf = M.info(name)
    local full = F.full()
    local w = full and F.worst() or nil
    local base = w and w.v or 0
    local function score(n)
        local i = M.info(n)
        if not i then return 0 end
        return math.max(0, F.value(n) - base) / math.max(1, tonumber(i.waxDuration) or 15)
    end
    local cr = D.Crates and D.Crates.crates and D.Crates.crates[name]
    if cr then
        local t = os.clock()
        while not F.crate and os.clock() - t < 3.5 do task.wait(0.05) end
        local c = F.crate
        if not (c and on("f_crates")) then return false end
        local ev = 0
        for _, it in ipairs(cr.contents or {}) do ev += (tonumber(it.chance) or 0) / 100 * score(it.butter) end
        local price = tonumber(c.price) or math.huge
        local limit = math.min(M.money() * (tonumber(val("f_crateMax", 25)) or 25) / 100, M.money() - F.keep())
        if ev <= score(h) or price > limit then F.lastErr = "crate not worth it" LOG("skip crate", name, "held", h) return false end
        LOG("sell for crate", h, "->", name)
        M.call("SellSquishy")
        local t2 = os.clock()
        while os.clock() - t2 < 2 and M.held() do task.wait(0.05) end
        if not M.held() then F.openCrate() end
        return true
    end
    if not inf or not inf.price or inf.rarity == "Limited" or M.rank(inf.rarity) < F.minRank() then F.lastErr = "rarity" return false end
    local v = F.value(name)
    if score(name) <= score(h) * 1.15 then F.lastErr = "not better" LOG("skip", name, "not better than", h) return false end
    if full and w and v <= w.v * 1.25 then F.lastErr = "worse" LOG("skip", name, "worse than stack") return false end
    local refund = F.heldPaid[h] or M.price(h) * 0.97
    if inf.price > M.money() + refund - F.reserve() - F.keep() then F.lastErr = "money" LOG("skip", name, "money") return false end
    M.call("SellSquishy")
    local t = os.clock()
    while os.clock() - t < 2 and M.held() do task.wait(0.05) end
    if M.held() then return false end
    if F.buy(name) then S.upgrades = (S.upgrades or 0) + 1 LOG("upgrade held", h, "->", name) return true end
    return false
end
