    while RUNNING do
        pcall(function()
            local money = M.money()
            local mins = math.max((os.clock() - S.t0) / 60, 0.1)
            local h = M.held()
            setText(UI.s1, __T["Doing: "] .. S.task .. ((F.lastErr ~= "" and S.task == "Rolling") and (__T[" (skip: "] .. F.lastErr .. ")") or ""))
            setText(UI.s2, string.format(__T["Cash %s · Income %s/s"], M.fmt(money), M.fmt(M.income())))
            setText(UI.s3, string.format(__T["Stack %d/%d · Waxing %d · Holding %s"], M.stackCount(), F.cap(), F.pouring(), h and (M.info(h) and M.info(h).displayName or h) or "-"))
            setText(UI.s4, string.format(__T["Rolls %d · Bought %d · Collected %s (%s/h)"], S.rolls, S.bought, M.fmt(S.collected), M.fmt(S.collected / mins * 60)))
            local parts = {}
            for _, r in ipairs(M.rarities) do if S.rar[r] and M.rank(r) >= 2 then parts[#parts + 1] = r .. " " .. S.rar[r] end end
            setText(UI.s5, (#parts > 0 and table.concat(parts, " · ") or __T["No rare butters yet"]) .. (S.best and (__T["\nBest: "] .. tostring(S.best.displayName)) or ""))
            local idx, price, owned, floors = F.nextStation()
            setText(UI.u1, string.format(__T["Stations %d · Floor %d\nNext: %s\nBought %d stations"], owned or 0, floors or 1, idx and ("#" .. idx .. __T[" for "] .. M.fmt(price)) or __T["need next floor"], S.stations))
            setText(UI.r1, string.format(__T["Claims %d · Helps %d · Crates %d · Pets %d · Trade-ups %d\nFree wax %d · Swaps %d"], S.claims, S.helps or 0, S.crates, S.pets, S.upgrades or 0, S.freeWax, S.swaps))
        end)
        task.wait(0.5)
    end
end)
